-- C11/P11.8 additive book performance truth/reconciliation. Repository-only.
create table if not exists public.command_center_book_performance_truth_history(
 owner_id uuid not null references auth.users(id) on delete cascade, metric_id text not null check(btrim(metric_id)<>''), project_id text not null, book_id text not null, edition text not null, format text not null, provider_key text not null, marketplace text not null, metric text not null check(metric in('sales','units','royalties','returns','refunds','pages_read','read_through','performance')), value numeric, currency text, truth text not null check(truth in('projected','estimated','confirmed','settled','disputed','adjusted')), period_start timestamptz not null, period_end timestamptz not null, source text not null, source_date timestamptz not null, observed_at timestamptz not null, freshness text not null check(freshness in('fresh','stale','unknown')), reconciliation text not null check(reconciliation in('unreconciled','reconciled','disputed','adjusted')), provider_record_ref text not null, settlement_ref text, source_refs text[] not null check(cardinality(source_refs)>0), primary key(owner_id,metric_id), unique(owner_id,provider_key,marketplace,provider_record_ref,metric,truth), check(value is null or value>=0), check(period_end>=period_start and observed_at>=period_end and observed_at>=source_date)
);
create or replace function public.command_center_reject_book_performance_truth_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book performance evidence is immutable'; end $$;
create trigger command_center_book_performance_truth_immutable before update or delete on public.command_center_book_performance_truth_history for each row execute function public.command_center_reject_book_performance_truth_mutation();
alter table public.command_center_book_performance_truth_history enable row level security; revoke all on table public.command_center_book_performance_truth_history from public,anon,authenticated; grant select,insert on table public.command_center_book_performance_truth_history to authenticated;
create policy p11_8_book_performance_truth_owner on public.command_center_book_performance_truth_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
